import sympy as sp, math
t=sp.symbols('t'); s,c,tn=sp.sin(t),sp.cos(t),sp.tan(t); se,cs,ct=1/c,1/s,1/tn
def idt(l,r):
    for v in (0.3,0.7,1.1):
        assert abs(float((l-r).subs(t,v)))<1e-9,(l,r)
R=sp.Rational; d=sp.pi/180; cl=math.isclose; r3=math.sqrt(3)
