for l,r in [((1-s**2)*se**2,1),(tn+ct,se*cs),((1+tn**2)*c**2,1),(s/(1+c)+(1+c)/s,2*cs),((se-tn)*(se+tn),1),(1/(1+s)+1/(1-s),2*se**2),
 (sp.sqrt((1-c)/(1+c)),cs-ct),((s+c)**2+(s-c)**2,2),(s**4-c**4,s**2-c**2),(c**4-s**4,1-2*s**2),(tn/(se-1),(se+1)/tn),(c/(1-tn)+s/(1-ct),s+c),
 ((1+ct-cs)*(1+tn+se),2),(se**2+cs**2,se**2*cs**2),((cs-s)*(se-c)*(tn+ct),1),((1-s)/(1+s),(se-tn)**2)]: idt(l,r)
